//! Shared fixture helpers.
//!
//! The fixture is a ~300-byte ONNX graph committed under `tests/fixtures/`,
//! regenerated by `cargo run -p cf-gears-onnx-scanner --features fixture-gen
//! --example generate_test_fixture`. See `tests/fixtures/README.md` for its
//! provenance.
//!
//! Everything here works with **no network and no files outside the repo**,
//! which is what lets these suites run in CI where the real 528 MB models
//! cannot.

#![allow(
    dead_code,
    reason = "each integration-test binary uses a different subset of these helpers"
)]
#![expect(
    clippy::expect_used,
    reason = "test helpers fail loudly on a broken fixture rather than return errors"
)]

use std::collections::BTreeMap;
use std::path::PathBuf;
use std::sync::{Arc, Mutex, PoisonError};
use std::time::Duration;

use onnx_scanner::runtime::config::{Checksum, ModelConfig, OutputDtype, Sha256Digest};
use onnx_scanner::runtime::metrics_port::{
    InferenceOutcome, InferenceTiming, LoadOutcome, NoopMetrics, RuntimeMetricsPort,
};

/// SHA-256 of `tests/fixtures/tiny.onnx`. Printed by the generator; update it
/// there and here together if the graph ever changes.
pub const FIXTURE_SHA256: &str = "234e1ae7863de405221537bf1e8d7fc7219783870d123d00effd781653cfbff2";

/// SHA-256 of `tests/fixtures/other.onnx`, the second fixture. Same rule as
/// [`FIXTURE_SHA256`]: the generator prints it, update both together.
pub const OTHER_FIXTURE_SHA256: &str =
    "979ea12f98024057501e1d5a3225de39eddae68d76ce1995ae99b932eb3bb266";

/// SHA-256 of `tests/fixtures/tokenizer.json`. Hand-written file: update this
/// whenever it is edited.
pub const TOKENIZER_SHA256: &str =
    "9d842d024c324bbddcfc76d08213e06c5fc5014ec3f3cb83f207c27a75be9a0d";

pub const MODEL_ID: &str = "tiny";
pub const OTHER_MODEL_ID: &str = "other";

pub fn digest(hex: &str) -> Sha256Digest {
    Sha256Digest::from_hex(hex).expect("a valid test digest")
}

pub fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

pub fn tokenizer_path() -> PathBuf {
    fixtures_dir().join("tokenizer.json")
}

/// Fails fast when no ONNX Runtime is configured.
///
/// Without this, a developer running these suites with `ORT_DYLIB_PATH` unset
/// would not get a failure — they would get a **hang**, because `ort`
/// 2.0.0-rc.12 blocks forever instead of erroring on a runtime it cannot load
/// (see `libs/ort-bootstrap`). An instant, legible error is worth the six lines.
///
/// Called from [`fixture_config`], so every test that builds a session gets it
/// without having to remember.
pub fn require_onnxruntime() {
    let configured = std::env::var("ORT_DYLIB_PATH")
        .ok()
        .filter(|p| !p.is_empty());
    let path = configured.as_deref().unwrap_or("");

    assert!(
        !path.is_empty() && std::path::Path::new(path).exists(),
        "ORT_DYLIB_PATH is unset or points at a missing file ({path:?}).\n\
         These tests load a real ONNX session, and `ort` hangs rather than erroring \
         when it cannot load a runtime — so this fails now instead of never.\n\
         Fix:  export ORT_DYLIB_PATH=\"$(bash scripts/fetch-onnxruntime.sh --path)\""
    );
}

/// The fixture's true contract: two inputs and two outputs, two dtypes, model
/// and tokenizer both pinned. Needs an ONNX Runtime to load.
pub fn fixture_config() -> ModelConfig {
    require_onnxruntime();
    fixture_config_without_runtime()
}

/// [`fixture_config`] without the runtime check, for tests whose load must
/// fail *before* any session is opened (and so never needs a runtime).
pub fn fixture_config_without_runtime() -> ModelConfig {
    ModelConfig {
        model_id: MODEL_ID.to_owned(),
        model_dir: fixtures_dir(),
        model_file: "tiny.onnx".to_owned(),
        tokenizer_file: "tokenizer.json".to_owned(),
        checksum: Checksum::Sha256(digest(FIXTURE_SHA256)),
        tokenizer_sha256: Some(digest(TOKENIZER_SHA256)),
        expected_inputs: vec!["ids".to_owned(), "weights".to_owned()],
        expected_outputs: vec!["ids_out".to_owned(), "scores".to_owned()],
        output_dtypes: output_dtypes(),
        replicas: 1,
        intra_threads: 1,
        ..ModelConfig::default()
    }
}

pub fn output_dtypes() -> BTreeMap<String, OutputDtype> {
    [
        ("ids_out".to_owned(), OutputDtype::I64),
        ("scores".to_owned(), OutputDtype::F32),
    ]
    .into_iter()
    .collect()
}

/// The second fixture's contract: one input fewer in common with the first
/// than any two copies of the same graph would be.
///
/// Different tensor names, different dtypes (`u8` and `bool`), and a different
/// tokenizer-free shape.
pub fn other_fixture_config() -> ModelConfig {
    require_onnxruntime();
    ModelConfig {
        model_id: OTHER_MODEL_ID.to_owned(),
        model_dir: fixtures_dir(),
        model_file: "other.onnx".to_owned(),
        tokenizer_file: "tokenizer.json".to_owned(),
        checksum: Checksum::Sha256(digest(OTHER_FIXTURE_SHA256)),
        tokenizer_sha256: Some(digest(TOKENIZER_SHA256)),
        expected_inputs: vec!["tokens".to_owned(), "marks".to_owned()],
        expected_outputs: vec!["tokens_out".to_owned(), "marks_out".to_owned()],
        output_dtypes: other_output_dtypes(),
        replicas: 1,
        intra_threads: 1,
        ..ModelConfig::default()
    }
}

pub fn other_output_dtypes() -> BTreeMap<String, OutputDtype> {
    [
        ("tokens_out".to_owned(), OutputDtype::U8),
        ("marks_out".to_owned(), OutputDtype::Bool),
    ]
    .into_iter()
    .collect()
}

pub fn other_fixture_with(mutate: impl FnOnce(&mut ModelConfig)) -> ModelConfig {
    let mut cfg = other_fixture_config();
    mutate(&mut cfg);
    cfg
}

pub fn fixture_with(mutate: impl FnOnce(&mut ModelConfig)) -> ModelConfig {
    let mut cfg = fixture_config();
    mutate(&mut cfg);
    cfg
}

/// A metrics port that records nothing, for tests that are not about metrics.
#[must_use]
pub fn no_metrics() -> Arc<dyn RuntimeMetricsPort> {
    Arc::new(NoopMetrics)
}

/// One recorded inference, as the metrics port saw it.
#[derive(Debug, Clone)]
pub struct RecordedInference {
    pub model_id: String,
    pub outcome: InferenceOutcome,
    pub timing: InferenceTiming,
}

/// One recorded model load: id, outcome label, resident-bytes estimate.
pub type RecordedLoad = (String, String, u64);

/// A metrics port that remembers what it was told.
///
/// Asserting through a port rather than by scraping an exporter keeps the tests
/// about *what is measured* rather than about OpenTelemetry's plumbing. Read it
/// through the accessors, which copy out, so no lock guard is ever held inside
/// an assertion.
#[derive(Default)]
pub struct RecordingMetrics {
    inferences: Mutex<Vec<RecordedInference>>,
    tokenizations: Mutex<Vec<(String, InferenceOutcome)>>,
    loads: Mutex<Vec<RecordedLoad>>,
    rebuilds: Mutex<Vec<(String, bool)>>,
    in_flight_deltas: Mutex<Vec<(String, i64)>>,
}

fn snapshot<T: Clone>(list: &Mutex<Vec<T>>) -> Vec<T> {
    list.lock().unwrap_or_else(PoisonError::into_inner).clone()
}

fn push<T>(list: &Mutex<Vec<T>>, item: T) {
    list.lock()
        .unwrap_or_else(PoisonError::into_inner)
        .push(item);
}

impl RecordingMetrics {
    #[must_use]
    pub fn inferences(&self) -> Vec<RecordedInference> {
        snapshot(&self.inferences)
    }

    #[must_use]
    pub fn tokenizations(&self) -> Vec<(String, InferenceOutcome)> {
        snapshot(&self.tokenizations)
    }

    #[must_use]
    pub fn loads(&self) -> Vec<RecordedLoad> {
        snapshot(&self.loads)
    }

    #[must_use]
    pub fn rebuilds(&self) -> Vec<(String, bool)> {
        snapshot(&self.rebuilds)
    }

    #[must_use]
    pub fn in_flight_deltas(&self) -> Vec<i64> {
        snapshot(&self.in_flight_deltas)
            .into_iter()
            .map(|(_, d)| d)
            .collect()
    }
}

impl RuntimeMetricsPort for RecordingMetrics {
    fn record_inference(&self, model_id: &str, outcome: InferenceOutcome, timing: InferenceTiming) {
        push(
            &self.inferences,
            RecordedInference {
                model_id: model_id.to_owned(),
                outcome,
                timing,
            },
        );
    }

    fn record_tokenize(&self, model_id: &str, outcome: InferenceOutcome, _elapsed: Duration) {
        push(&self.tokenizations, (model_id.to_owned(), outcome));
    }

    fn record_in_flight_delta(&self, model_id: &str, delta: i64) {
        push(&self.in_flight_deltas, (model_id.to_owned(), delta));
    }

    fn record_model_load(
        &self,
        model_id: &str,
        outcome: LoadOutcome,
        _elapsed: Duration,
        resident_bytes: u64,
    ) {
        push(
            &self.loads,
            (
                model_id.to_owned(),
                outcome.as_label().to_owned(),
                resident_bytes,
            ),
        );
    }

    fn record_session_rebuild(&self, model_id: &str, succeeded: bool) {
        push(&self.rebuilds, (model_id.to_owned(), succeeded));
    }
}
